ROOT=Path('/root/hollowdeep-dev')
BINARY_SHA='26c806cf59b159555f8c0ec73f5daa0c0b0516d99bced49487c30cde0397bde7'
def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def check_profile(src):
    fingerprints={name:digest(src/name) for name in EXPECTED}
    if fingerprints!=EXPECTED:
        for n in EXPECTED: print(f'{n}: actual {fingerprints[n]}; expected {EXPECTED[n]}',flush=True)
        raise SystemExit('CACHE: rejected mismatched source; nothing patched')
    player=(src/'player.c').read_text('latin-1')
    start=player.index('char *title_ply(')
    title=player[start:player.index('void compute_ac(',start)]
    if 'hd_store_is_necromancer(ply_ptr->name)' not in title or 'return necromancer_title;' not in title or '"Necromancer"' not in title:
        raise SystemExit('Expected verified native class-title hook missing; no patch applied')

def patch_source(src,pkg):
    check_profile(src)
    diff=pkg/'cache.patch'
    for dry in (True,False):
        args=['patch','-p1','--fuzz=0','--batch','--forward','-i',str(diff)]
        if dry: args.insert(1,'--dry-run')
        subprocess.run(args,cwd=src,check=True,stdout=subprocess.DEVNULL)
    for n,sha in AFTER.items():
        if digest(src/n)!=sha: raise SystemExit('Patched fingerprint mismatch: '+n)
    print('CACHE: exact private source profile and output fingerprints PASS',flush=True)

def checks(src,pkg,qa,abi):
    qa.mkdir(mode=0o700)
    fixture=qa/'fixture';fixture.mkdir(mode=0o700)
    shutil.copytree(pkg/'help',fixture/'help')
    print('CACHE: seven updated ASCII native help files staged',flush=True)
    flags=[os.environ.get('CC','cc'),abi,'-std=gnu89','-O1','-g','-fcommon',
           '-DHD_NECROMANCER_PLAYTEST','-DHD_DEITY_PLAYTEST','-DHD_CORPSE_PLAYTEST',
           '-ffunction-sections','-fdata-sections','-Wl,--gc-sections','-Wno-implicit-function-declaration',
           '-Wno-int-conversion','-Wno-incompatible-pointer-types','-Wno-return-type','-I',str(src)]
    def run_logged(argv,label,cwd):
        path=qa/(label+'.log')
        with path.open('wb') as f:
            run=subprocess.run(argv,cwd=cwd,stdout=f,stderr=subprocess.STDOUT)
        if run.returncode:
            print(path.read_text(errors='replace')[-6000:],flush=True)
            raise RuntimeError(label+' failed; see '+str(path))
    for name,sources,extras in (
        ('cache-native',['hd_corpse.c','hd_necro_skeleton.c','files1.c','files2.c','global.c','player.c','room.c'],['-Wl,--wrap=load_obj','-Wl,--wrap=add_permcrt_rom']),
        ('corpse',['hd_corpse.c','hd_necro_skeleton.c'],[]),
        ('healing',['hd_necro_skeleton.c','magic1.c','magic2.c','magic3.c'],[]),
        ('help',['hollowdeep_help.c'],[])):
        test={'cache-native':'test_cache_native.c','corpse':'test_corpse.c','healing':'test_healing.c','help':'test_help.c'}[name]
        exe=qa/name
        run_logged(flags+extras+[str(src/n) for n in sources]+[str(pkg/test),'-o',str(exe)],name+'-compile',qa)
        subprocess.run([str(exe)],cwd=fixture,check=True)
    for mode in ('legacy','private'):
        definitions=[] if mode=='legacy' else ['-DHD_NECROMANCER_PLAYTEST','-DHD_DEITY_PLAYTEST','-DHD_CORPSE_PLAYTEST','-DHD74_PRIVATE_NATIVE']
        for n in ('files1.c','files2.c','global.c'):
            run_logged([flags[0],abi,'-std=gnu89','-fcommon','-Wno-implicit-function-declaration','-Wno-int-conversion','-Wno-incompatible-pointer-types','-Wno-return-type','-fsyntax-only','-I',str(src)]+definitions+[str(src/n)],mode+'-'+n,qa)
        print('CACHE: '+mode+' native syntax PASS',flush=True)
    if abi=='-m32':
        run_logged(['make','-s','-B','-j2','NECROMANCER_PLAYTEST=1','DEITY_PLAYTEST=1','CORPSE_PLAYTEST=1'],'full-build',src)
        if (src/'frp.new').open('rb').read(5)!=b'\x7fELF\x01': raise RuntimeError('Expected ELF32 build')
        print('CACHE: new private native ELF32 build PASS',flush=True)
        print('CACHE: PRIVATE CORPSE/PET ROOM CACHE + TITLE + HELP ELF32 PASS',flush=True)

def pid():
    p=subprocess.check_output(['systemctl','show','hollowdeep.service','-p','MainPID','--value'],text=True).strip()
    if not p.isdigit() or int(p)<1: raise SystemExit('Expected an active production service')
    return p

def main():
    os.umask(0o077)
    if len(sys.argv)!=2: raise SystemExit('Usage: onepass_linode.py VERIFIED_PRIVATE_CORPSE_SRC')
    raw=Path(sys.argv[1]);src=raw.resolve(strict=True)
    if raw.is_symlink() or src!=ROOT/'necromancer-playtest-corpse-3nl5y8b7'/'src' or any(x.is_symlink() for x in src.rglob('*')):
        raise SystemExit('Refusing unapproved or symlinked source')
    if digest(src/'frp.new')!=BINARY_SHA: raise SystemExit('Accepted gameplay-tested binary mismatch')
    check_profile(src)
    before=pid()
    work=Path(tempfile.mkdtemp(prefix='necromancer-playtest-cache-',dir=ROOT))
    print('PRIVATE CACHE BUILD: '+str(work),flush=True)
    pkg=work/'pkg';pkg.mkdir(mode=0o700)
    for n,body in PAYLOAD.items():
        dest=pkg/n;dest.parent.mkdir(exist_ok=True,parents=True);dest.write_text(body,encoding='ascii')
    try:
        shutil.copytree(src,work/'src')
        patch_source(work/'src',pkg)
        checks(work/'src',pkg,work/'qa','-m32')
        if digest(src/'frp.new')!=BINARY_SHA: raise RuntimeError('Original private executable changed')
    finally:
        if pid()!=before: raise SystemExit('Production PID changed; check service')
        print('PRODUCTION SERVICE PID: UNCHANGED',flush=True)
    print('PRODUCTION DEPLOYMENT: NONE',flush=True)
    print('PRIVATE SOURCE: '+str(work/'src'),flush=True)
    print('PRIVATE RESULTS: '+str(work/'qa'),flush=True)

if __name__=='__main__': main()
